import hmac, time
def verify_otp(session, input_code):
    if time.time() > session['expires_at']:
        return False, 'expired'
    if session['attempts'] >= 3:
        return False, 'locked'
    session['attempts'] += 1
    valid = hmac.compare_digest(session['code'], input_code)
    return valid, 'ok' if valid else 'invalid'
